css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.label{ margin: 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; max-width: 320px; }
.embed-slot{ display: block; width: 100%; }
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }
.label{ font-size: 15px; }}
.history-section { padding-top: 150px; padding-bottom: 150px; background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.history-intro { display: flex; flex-direction: column; align-items: center; gap: 28px; padding-bottom: 72px; text-align: center; }
.history-lead { max-width: 1000px; margin: 0; font-size: 40px; line-height: 1.18; font-weight: 400; letter-spacing: -0.02em; }
.history-skip-link { font-size: 15px; line-height: 1.4; color: rgba(255, 255, 255, 0.62); text-decoration: underline; text-underline-offset: 4px; }
.history-skip-link:hover { color: #ffffff; }
.quiz-area { margin-top: 120px; padding-left: 20px; padding-right: 20px; scroll-margin-top: 160px; }

@media screen and (max-width: 991px) {
  .history-section { padding-top: 112px; padding-bottom: 112px; }
  .history-lead { font-size: 34px; }
  .quiz-area { margin-top: 96px; }
}
@media screen and (max-width: 767px) {
  .history-section { padding-top: 88px; padding-bottom: 88px; }
  .history-intro { gap: 20px; padding-bottom: 48px; }
  .history-lead { font-size: 28px; }
  .quiz-area { margin-top: 72px; }
}
@media screen and (max-width: 479px) {
  .history-lead { font-size: 25px; }
}
